-- Дополнение правила про fill_blanks: помимо пояснения ЧТО проверяется,
-- нода-преамбула теперь обязана объяснить КАК физически отвечать (тап по
-- точкам) — автор не должен считать это очевидным для новичка.
--
-- Проверено на конфликт: апдейт целится только в старую формулировку
-- (WHERE ловит текст без нового маркера "физически действовать").
update public.lesson_rules
set rule_text = 'Перед КАЖДОЙ нодой fill_blanks («Составь предложение») обязательна короткая текстовая нода-пояснение прямо перед ней — простыми словами, какая форма/что именно проверяется (например «Проверим настоящее время» или «А теперь — прошедшее»), И как физически действовать — упомяни тап по точкам/пропускам простыми словами («тапни на точки и выбери», «жми на точки внизу»), не предполагай, что ученик и так знает механику модуля с первого раза. Тон разговорный, не техническое ТЗ («заполни пропуск буквой», «выбери верную форму» — плохо; «Как звучит настоящее время? Тапни на точки и заполни» — хорошо). Без такого пояснения ученик видит фразу с дырками без контекста: непонятно, какое именно правило проверяется, почему тут вообще есть дырка и что вообще нажимать.'
where rule_text like 'Перед КАЖДОЙ нодой fill_blanks%'
  and rule_text not like '%физически действовать%';

-- Новые правила: неформальный «дружеский» тон переписки (Пит, не
-- преподаватель); примеры-ситуации — реальные события из жизни Пита, не
-- абстрактные сценки; после верного ответа перевод не повторяет собранную
-- фразу дословно; перевод красится белым курсивом без bold/underline;
-- изредка уместны неформальные чат-привычки поколения альфа.
insert into public.lesson_rules (rule_text, sort_order, category)
select v.rule_text, v.sort_order, 'principle'
from (values
  ('Весь урок — переписка с ДРУГОМ (Пит), а не с преподавателем: у Пита неформальный, живой вайб, а не учительский/канцелярский слог. Пиши как в мессенджере: короткие реплики, разговорные словечки («короче», «кстати», «ну», «ага», «блин»), никаких «Верно!»/«Совершенно верно»/«Ровно так» подряд из урока в урок — это звучит как автоответчик. ✗ «Не в этот раз — тут новый паттерн, смотри:» ✓ «А вот тут уже по-другому, смотри:». ✗ «Вот это финал 👏» ✓ «Ну всё, теперь ты в теме 😏». Проверяй КАЖДУЮ реплику-подтверждение на этот тон, а не только «крупные» сообщения.', 184),
  ('Примеры-ситуации в упражнениях — это то, что происходит В ЖИЗНИ САМОГО ПИТА (у него есть друзья, планы, дни рождения, привычки), а не безличные абстрактные сценки «он/она делает X». Формулируй через что Пит услышал/увидел/прочитал/узнал от друга — «кстати, Маша с Андреем завтра впервые идут в караоke 😄», «у меня скоро день рождения, скорее бы торт 🎂» — а не «На каждом празднике — новый торт» или «Мы никогда не играли в шахматы — и наконец решились» (это абстрактно и слишком литературно для чата с другом). Пример живой, если его реально можно представить как сообщение от знакомого, а не как строчку из учебника.', 185),
  ('После верного ответа реплика (если она вообще нужна, см. отдельный принцип про реакцию) НЕ повторяет дословно только что собранную фразу целиком — это читается как «эхо», а не как ответ живого человека. Дай ёмкий, естественный ПЕРЕВОД или комментарий, а не повтор-подтверждение той же строки. ✗ «You try to speak English 👍 / Точно — you try to speak English, ты пробуешь говорить по-английски» (фраза повторена дважды подряд) ✓ «Почти! Вот так I try to listen значит: я пытаюсь слушать» — фраза внутри реплики упоминается РОВНО ОДИН раз, дальше сразу перевод. Также не используй одну и ту же реплику-подтверждение («Ровно так — ...», «Именно так — ...») в РАЗНЫХ упражнениях подряд по уроку — вариативность нужна и здесь, не только в самих примерах.', 186),
  ('Перевод на русский (когда он явно назван как перевод английской фразы — что значит фраза целиком или отдельная её часть) красится БЕЛЫМ КУРСИВОМ (mode: text, color: #fdfcfc + отдельный highlight с курсивом), БЕЗ bold и БЕЗ underline. Bold+underline (с брендовым/акцентным цветом) остаётся ТОЛЬКО за смысловым акцентом урока — конкретным грамматическим элементом, который разбирается прямо сейчас («to здесь — мостик между глаголами»). Это касается перевода где угодно: отдельной репликой («значит: я пытаюсь слушать»), внутри текста задания («Собери: «Ты пробуешь танцевать»»), и даже когда прямого перевода нет, но фраза на русском по сути пересказывает ту же мысль, которую предстоит собрать («Что он делает?» перед заданием про его привычку) — такая фраза тоже красится белым курсивом.', 187),
  ('Иногда (не в каждой реплике, через раз-два) можно использовать живые чат-привычки поколения альфа/зумеров вместо стандартных эмодзи-улыбок: одинарная/двойная закрывающая скобка вместо смайла («самое то)», «ну наконец-то))»), «ору» или «кек» как маркер «это смешно», нарочито растянутое слово («не-е-ет»), эмодзи 😭 в ироничном смысле (не «плачу», а «это перебор/очень смешно»). Не переусердствуй — если в КАЖДОМ сообщении есть «))» или «ору», это тоже читается неестественно, как переигрывание.', 188)
) as v(rule_text, sort_order)
where not exists (
  select 1 from public.lesson_rules where rule_text = v.rule_text
);
